import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        int n = r.nextInt();
        long limit = r.nextLong();
        long[] capacity = new long[n], secondary = new long[n];
        boolean over = false;
        for (int i = 0; i < n; i++) {
            long p = r.nextLong();
            if (p > limit) over = true;
            capacity[i] = limit - p;
        }
        for (int i = 0; i < n; i++) secondary[i] = r.nextLong();
        if (over) { System.out.println(-1); return; }
        Arrays.sort(capacity);
        Arrays.sort(secondary);
        int answer = 0;
        for (long c : capacity)
            if (answer < n && secondary[answer] <= c) answer++;  // smallest unused task into the smallest capacity
        System.out.println(answer);
    }
}


final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

